// news 資料表保存與台灣有關的新聞索引；第一批來源是 GDELT 的事件與報導連結，只存網址與後設資料，不存全文。

package services

import (
	"context"
	"fmt"

	"github.com/maoxiaoyue/hypgo/pkg/errors"
	"github.com/maoxiaoyue/hypgo/pkg/hidb"
	"github.com/maoxiaoyue/hypgo/pkg/logger"
	"github.com/uptrace/bun"
)

// ErrNewsSchemaFailed 為建立 news 資料表失敗；交易已回滾。
//
// @ai:generated by=claude-opus-5-5 date=2026-11-06
var ErrNewsSchemaFailed = errors.Define("E8001", 500, "News schema setup failed", "news")

// NewsTables 列出 news schema 應有的資料表。
//
// @ai:generated by=claude-opus-5-5 date=2026-11-06
var NewsTables = []string{"gdelt_events", "articles", "article_events"}

// newsSchemaStatements 可重複執行；中國大陸網域的報導在匯入時就排除，所以 source_region 沒有 CN。
var newsSchemaStatements = []string{
	`CREATE SCHEMA IF NOT EXISTS news`,

	// taiwan_match 記錄是哪個欄位讓事件被判定與台灣有關，之後可以只看台灣是行為者的事件。
	`CREATE TABLE IF NOT EXISTS news.gdelt_events (
		global_event_id bigint PRIMARY KEY,
		event_date date NOT NULL,
		actor1_code text,
		actor1_name text,
		actor1_country text,
		actor2_code text,
		actor2_name text,
		actor2_country text,
		event_code text NOT NULL,
		event_root_code text NOT NULL,
		quad_class smallint,
		goldstein real,
		avg_tone real,
		num_mentions integer,
		num_sources integer,
		num_articles integer,
		action_geo_name text,
		action_geo_country text,
		action_lat double precision,
		action_lon double precision,
		taiwan_match text[] NOT NULL,
		translated boolean NOT NULL,
		date_added timestamptz NOT NULL,
		fetched_at timestamptz NOT NULL DEFAULT now()
	)`,
	`CREATE INDEX IF NOT EXISTS gdelt_events_date_idx ON news.gdelt_events (event_date)`,
	`CREATE INDEX IF NOT EXISTS gdelt_events_fetched_idx ON news.gdelt_events (fetched_at)`,

	// title 先留空：GDELT 事件檔沒有標題，之後由其他來源補上。
	`CREATE TABLE IF NOT EXISTS news.articles (
		article_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
		url text NOT NULL UNIQUE,
		domain text NOT NULL,
		source_region text NOT NULL CHECK (source_region IN ('TW', 'HK', 'foreign')),
		language text,
		first_seen_at timestamptz NOT NULL,
		doc_tone real,
		doc_length integer,
		title text,
		provider text NOT NULL DEFAULT 'gdelt',
		fetched_at timestamptz NOT NULL DEFAULT now(),
		updated_at timestamptz NOT NULL DEFAULT now()
	)`,
	`CREATE INDEX IF NOT EXISTS articles_seen_idx ON news.articles (first_seen_at)`,
	`CREATE INDEX IF NOT EXISTS articles_domain_idx ON news.articles (domain)`,
	`CREATE INDEX IF NOT EXISTS articles_updated_idx ON news.articles (updated_at)`,

	`CREATE TABLE IF NOT EXISTS news.article_events (
		article_id bigint NOT NULL REFERENCES news.articles (article_id) ON DELETE CASCADE,
		global_event_id bigint NOT NULL REFERENCES news.gdelt_events (global_event_id) ON DELETE CASCADE,
		mentioned_at timestamptz NOT NULL,
		confidence smallint,
		in_raw_text boolean,
		sentence_id integer,
		PRIMARY KEY (article_id, global_event_id)
	)`,
	`CREATE INDEX IF NOT EXISTS article_events_event_idx ON news.article_events (global_event_id)`,
}

// EnsureNewsSchema 在單一交易內建立 news 資料表；可重複執行。
//
// @ai:generated by=claude-opus-5-5 date=2026-11-06
// @ai:purpose 匯入新聞前先固定結構；全部成功才生效，不會留下半套資料表
// @ai:input ctx, db 資料庫, log
// @ai:output error（ErrNewsSchemaFailed）
// @ai:sideeffect 建立 news schema、資料表與索引
func EnsureNewsSchema(ctx context.Context, db *hidb.Database, log *logger.Logger) error {
	err := db.HypDBTransaction(ctx, func(ctx context.Context, tx bun.Tx) error {
		for i, stmt := range newsSchemaStatements {
			if _, err := tx.ExecContext(ctx, stmt); err != nil {
				return fmt.Errorf("statement %d: %w", i+1, err)
			}
		}
		var found int
		if err := tx.NewRaw(`SELECT count(*) FROM pg_tables WHERE schemaname = 'news' AND tablename IN (?)`,
			bun.In(NewsTables)).Scan(ctx, &found); err != nil {
			return fmt.Errorf("verify tables: %w", err)
		}
		if found != len(NewsTables) {
			return fmt.Errorf("found %d of %d tables", found, len(NewsTables))
		}
		return nil
	})
	if err != nil {
		log.Error("setup news schema failed", "err", err)
		return ErrNewsSchemaFailed.With("reason", err.Error())
	}
	return nil
}
